.hero-glaze {
    z-index: -1;
    pointer-events: none;
    position: absolute;
    inset: 0
}

.hero-glaze:before {
    content: "";
    inset-block: 0;
    background: linear-gradient(90deg, #0000, #ffffff59, #0000);
    width: 45%;
    animation: 5s cubic-bezier(.4, 0, .2, 1) 1.2s 3 hero-glaze;
    position: absolute;
    left: 0;
    transform: translate(-100%)skew(-20deg)
}

