    0% {
        opacity: .5;
        transform: scale(1)
    }

    to {
        opacity: 0;
        transform: scale(1.8)
    }
}

@media (hover:hover) {
    .group:hover .hero-play-ripple {
        animation: 1.2s cubic-bezier(.22, 1, .36, 1) infinite hero-play-ripple
    }
}

.group:focus-visible .hero-play-ripple {
    animation: 1.2s cubic-bezier(.22, 1, .36, 1) infinite hero-play-ripple
}

