    to {
        opacity: 0
    }

    21%,
    79% {
        opacity: 1
    }
}

.customize-ring {
    border-radius: inherit;
    pointer-events: none;
    opacity: 0;
    background: conic-gradient(in oklab from var(--customize-ring-angle), transparent 0deg, #3b82f61a 45deg, #6366f159 85deg, #8b5cf6 115deg, #d946ef 135deg, #ec4899 150deg, #f97316 170deg, #f59e0b59 200deg, #10b9811a 240deg, transparent 275deg);
